__attribute__((target("avx2,fma")))
void radix29_z_t2csght_bwd_avx2(
    const double *            zin,
    const double *            zin_unused,
    double       *            zout,
    double       *            zout_unused,
    const double * tw_re, const double * tw_im,
    size_t Ls, size_t Gs, size_t OLs, size_t OGs, size_t count)
{
    /* t2csght: the transposed group loop reading the HALF SPECTRUM: zin = the caller's spectrum, zin_unused = obase (its natural bases, scaled, stride count), zout_unused = its mirror base (in + 2N); Ls / OLs = the leg stride and column pitch there; the blocks go out in block order (a last stage: one column per block, leg stride 1, column pitch R). Gs = groups; one call per stage. */
    const size_t *obase = (const size_t *)zin_unused;
    for (size_t g = 0; g < Gs; g++)   /* a last stage: one column per block */
        _t2csght29_body(zin + 2 * obase[g * count], zout_unused,
                        zout + 2 * (g * count * 29), zin,
                        tw_re, tw_im + 8 * g, Ls, OLs, 1, 29, count);
}
